<script setup lang="ts">
import { computed, ref } from 'vue'
import { useAppStore } from '../../stores/appStore'
import { gradeColor } from '../../utils/calculations'
const { programmes, sessions, semesters, subjects, students, marksEntries, semesterResults, currentUser, approveResult, addAuditLog } = useAppStore()
const selSession = ref('s2'); const selSem = ref(''); const selectedId = ref<string | null>(null); const message = ref(''); const correctionReason = ref('')
const activeResults = computed(() => semesterResults.value.filter(result => result.publicationStatus !== 'published' && result.sessionId === selSession.value && (!selSem.value || result.semesterId === selSem.value)))
const pending = computed(() => activeResults.value.filter(result => result.publicationStatus === 'draft'))
const approved = computed(() => activeResults.value.filter(result => result.publicationStatus === 'approved'))
const selected = computed(() => semesterResults.value.find(result => result.id === selectedId.value))
const selectedStudent = computed(() => students.value.find(student => student.id === selected.value?.studentId))
const selectedSemester = computed(() => semesters.value.find(semester => semester.id === selected.value?.semesterId))
const selectedProgramme = computed(() => programmes.value.find(programme => programme.id === selectedStudent.value?.programmeId))
const selectedSubjects = computed(() => subjects.value.filter(subject => subject.programmeId === selectedStudent.value?.programmeId && subject.semesterNumber === selectedSemester.value?.number))
const selectedEntries = computed(() => marksEntries.value.filter(entry => entry.studentId === selected.value?.studentId && entry.semesterId === selected.value?.semesterId))
const sessionOptions = computed(() => sessions.value)
const semesterOptions = computed(() => semesters.value.filter(semester => semester.sessionId === selSession.value))
const canApprove = computed(() => currentUser.value?.role === 'admin')
function approve() { if (!canApprove.value) { message.value = 'Only administrators can approve results.'; return }; if (!selected.value || !window.confirm('Are you sure you want to approve this result?')) return; approveResult(selected.value.id); message.value = 'Result approved and ready for publication.'; selectedId.value = null }
function returnForCorrection() { if (!selected.value || !correctionReason.value.trim()) { message.value = 'Enter a reason before returning the result.'; return }; if (!window.confirm('Return this result for correction?')) return; addAuditLog('RETURN_FOR_CORRECTION', 'SemesterResult', `${selectedStudent.value?.name ?? selected.value.studentId}: ${correctionReason.value.trim()}`); message.value = 'Correction request recorded in the audit trail.'; correctionReason.value = ''; selectedId.value = null }
</script>
<template>
  <div class="space-y-5"><section class="rounded-xl border border-navy-100 bg-white p-5"><div class="mb-4"><p class="text-xs font-medium uppercase tracking-wider text-gold-600">Examination Control</p><h2 class="font-serif text-xl font-semibold text-navy-900">Result Approval</h2><p class="text-sm text-navy-500">Review processed results before they become eligible for publication.</p></div><div class="grid grid-cols-2 gap-4"><label class="text-xs font-medium text-navy-600">Academic Session<select v-model="selSession" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2 text-sm"><option v-for="session in sessionOptions" :key="session.id" :value="session.id">{{ session.name }}</option></select></label><label class="text-xs font-medium text-navy-600">Semester<select v-model="selSem" class="mt-1 w-full rounded-lg border border-navy-200 px-3 py-2 text-sm"><option value="">All semesters</option><option v-for="semester in semesterOptions" :key="semester.id" :value="semester.id">{{ semester.name }}</option></select></label></div><div class="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-3"><div class="rounded-lg border border-amber-200 bg-amber-50 p-4"><div class="text-2xl font-serif font-bold text-amber-700">{{ pending.length }}</div><div class="text-xs text-amber-700">Pending approval</div></div><div class="rounded-lg border border-blue-200 bg-blue-50 p-4"><div class="text-2xl font-serif font-bold text-blue-700">{{ approved.length }}</div><div class="text-xs text-blue-700">Approved</div></div><div class="rounded-lg border border-navy-100 bg-navy-50 p-4"><div class="text-2xl font-serif font-bold text-navy-900">{{ activeResults.length }}</div><div class="text-xs text-navy-600">In review</div></div></div><div v-if="message" class="mt-4 rounded-lg bg-gold-50 px-3 py-2 text-sm text-gold-700">{{ message }}</div></section>
+    <section class="overflow-hidden rounded-xl border border-navy-100 bg-white"><div class="overflow-x-auto"><table class="w-full min-w-190 text-sm"><thead><tr class="bg-navy-50/50 text-left text-xs uppercase tracking-wider text-navy-500"><th class="px-5 py-3">Student</th><th class="px-5 py-3">Programme</th><th class="px-3 py-3">Semester</th><th class="px-3 py-3">Courses</th><th class="px-3 py-3">Credits</th><th class="px-3 py-3">GPA</th><th class="px-3 py-3">CGPA</th><th class="px-3 py-3">Result</th><th class="px-5 py-3">Status</th><th /></tr></thead><tbody class="divide-y divide-navy-50"><tr v-for="result in activeResults" :key="result.id"><td class="px-5 py-3"><div class="font-medium text-navy-800">{{ students.find(student => student.id === result.studentId)?.name }}</div><div class="text-xs text-navy-400">{{ students.find(student => student.id === result.studentId)?.studentId }}</div></td><td class="px-5 py-3 text-xs">{{ programmes.find(programme => programme.id === students.find(student => student.id === result.studentId)?.programmeId)?.name }}</td><td class="px-3 py-3 text-xs">{{ semesters.find(semester => semester.id === result.semesterId)?.name }}</td><td class="px-3 py-3 text-center">{{ subjects.filter(subject => subject.programmeId === students.find(student => student.id === result.studentId)?.programmeId).length }}</td><td class="px-3 py-3 text-center font-mono">{{ result.earnedCredits }}/{{ result.totalCredits }}</td><td class="px-3 py-3 text-center font-mono font-bold">{{ result.gpa.toFixed(2) }}</td><td class="px-3 py-3 text-center font-mono">{{ result.cgpa.toFixed(2) }}</td><td class="px-3 py-3 text-center"><span class="rounded-full px-2 py-0.5 text-xs" :class="result.overallStatus === 'pass' ? 'bg-emerald-50 text-emerald-700' : 'bg-red-50 text-red-700'">{{ result.overallStatus.toUpperCase() }}</span></td><td class="px-5 py-3"><span class="rounded-full bg-navy-50 px-2 py-0.5 text-xs text-navy-600">{{ result.publicationStatus === 'draft' ? 'Pending Approval' : 'Approved' }}</span></td><td class="px-5 py-3"><button class="text-xs text-navy-700 hover:text-gold-700" @click="selectedId = result.id">Review</button></td></tr></tbody></table><div v-if="!activeResults.length" class="p-12 text-center text-sm text-navy-400">No processed results are waiting for approval.</div></div></section>
